export class ScriptSyntaxError extends Error {
    code;
    sourceName;
    offset;
    constructor(code, message, sourceName, offset) {
        super(`${code}: ${message}${offset === undefined ? "" : ` (${sourceName}:${offset})`}`);
        this.name = "ScriptSyntaxError";
        this.code = code;
        this.sourceName = sourceName;
        this.offset = offset;
    }
}
